import collections,gzip,json,pathlib
out=pathlib.Path(__file__).resolve().parent

def read(name):
 p=out/name
 if not p.exists():p=pathlib.Path(str(p)+'.gz')
 return (gzip.open(p,'rt') if p.suffix=='.gz' else p.open()).read()
def load(name):return json.loads(read(name))
def stream(name):return [json.loads(s) for s in read(name).splitlines() if s.strip()]
def short(s):return s.replace('/workspace/scratch/ff5eddz-adapted/','')
def esc(s):return str(s).replace('|','\\|').replace('\n','<br>')
def finding(f):return 'none' if not f else f"{f.get('phase','')} / {f['kind']} / {short(f['where'])} / {f['reason']}"
def key(f):return tuple(f.get(k,'') for k in ('phase','kind','where','reason'))
def order(f):
 p,l,c=f['where'].rsplit(':',2);return p,int(l),int(c),f.get('phase',''),f['reason']
names=load('source-names.json')
def owner(where):
 p,l,c=where.rsplit(':',2)
 source=pathlib.Path(p).read_bytes().decode('utf-8')
 # Unit location positions are UTF-16 columns. All declaration prefixes here are ASCII.
 pos=sum(len(x.encode('utf-16-le'))//2 for x in source.splitlines(keepends=True)[:int(l)-1])+int(c)-1
 ds=names.get(p,{}).get('declarations',[])
 candidates=[d for d in ds if d['start']<=pos<d['end']]
 return min(candidates,key=lambda d:d['end']-d['start'])['name'] if candidates else '<top-level>'
