for mode in ('tracing','entry'):
 for side in ('parent','head'):
  t=load(f'{mode}-{side}.time.json');lines.append(f"| {mode} {side} | {t['exit']} | {t['wall_seconds']:.3f} | {t['peak_rss_kib']} |")
lines+=['','## tracing.ts, every finding in source order','',
'Exact reasons appear below. Identical phase/kind/location/reason rows repeated across attempt contexts are quoted once with their occurrence counts; the raw streams retain every occurrence. Findings attributed to other files are retained in the streams and pair ledgers.','',
'| Location | Phase | Kind | Exact reason | Parent occurrences | Head occurrences | Change |','| --- | --- | --- | --- | ---: | ---: | --- |']
traces={s:stream(f'tracing-{s}.jsonl') for s in ('parent','head')}
fs={s:[f for row in rows[1:] for f in row.get('findings',[]) if '/src/compiler/tracing.ts:' in f['where']] for s,rows in traces.items()}
counts={s:collections.Counter(key(f) for f in arr) for s,arr in fs.items()}
allf={key(f):f for arr in fs.values() for f in arr}
for k,f in sorted(allf.items(),key=lambda x:order(x[1])):
 b,h=counts['parent'][k],counts['head'][k]
 change='unchanged' if b and h else ('cleared' if b else 'new')
 lines.append('| '+' | '.join(map(esc,[short(f['where']),f.get('phase',''),f['kind'],f['reason'],b,h,change]))+' |')
lines+=['','Additional findings reached by the tracing attempts but attributed to checker.ts (unchanged on both sides):','', '| Location | Phase | Kind | Exact reason |','| --- | --- | --- | --- |']
dependencies={key(f):f for r in traces['head'][1:] for f in r.get('findings',[]) if '/src/compiler/tracing.ts:' not in f['where']}
